<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('programme_manager');
require_once __DIR__ . '/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='budgets';$pageTitle='Budget & Expenditure';$flashes=render_flashes();$errors=[];$tableReady=pm_table_exists($conn,'programme_budgets');$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);

$expenseReady=pm_table_exists($conn,'programme_expenditures');$editing=['id'=>0,'programme_id'=>0,'cohort_id'=>0,'fiscal_period'=>'Current period','allocated_amount'=>'','notes'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!validate_csrf())$errors[]='Session validation failed. Refresh and try again.';
 elseif(!$tableReady||!$expenseReady)$errors[]='Import database/programme_management_suite.sql before saving financial records.';
 else {$action=(string)($_POST['action']??'');$pid=(int)($_POST['programme_id']??0);$cid=(int)($_POST['cohort_id']??0);if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Choose a programme and cohort within your assigned scope.';
 if($action==='budget'){$amount=filter_var($_POST['allocated_amount']??null,FILTER_VALIDATE_FLOAT);$period=trim((string)($_POST['fiscal_period']??''));$notes=trim((string)($_POST['notes']??''));if($amount===false||$amount<0)$errors[]='Enter a valid non-negative budget amount.';if($period===''||strlen($period)>40)$errors[]='Enter a reporting period of up to 40 characters.';if(!$errors){$cv=$cid?:null;$s=$conn->prepare('INSERT INTO programme_budgets(programme_id,cohort_id,fiscal_period,allocated_amount,notes,created_by) VALUES(?,?,?,?,?,?)');if($s){$s->bind_param('iisdsi',$pid,$cv,$period,$amount,$notes,$managerId);if($s->execute()){ $s->close();set_flash('success','Budget saved','The programme allocation has been recorded.');safe_redirect('programme/budgets.php');}$s->close();}$errors[]='The budget could not be saved.';}}
 elseif($action==='expense'){$date=(string)($_POST['expense_date']??'');$category=trim((string)($_POST['category']??''));$desc=trim((string)($_POST['description']??''));$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$ref=trim((string)($_POST['reference_number']??''));$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)$errors[]='Choose a valid expenditure date.';if($category===''||strlen($category)>100)$errors[]='Enter an expenditure category.';if($desc===''||strlen($desc)>255)$errors[]='Enter a description of up to 255 characters.';if($amount===false||$amount<=0)$errors[]='Expenditure must be greater than zero.';if(!$errors){$cv=$cid?:null;$rv=$ref?:null;$s=$conn->prepare('INSERT INTO programme_expenditures(programme_id,cohort_id,expense_date,category,description,amount,reference_number,recorded_by) VALUES(?,?,?,?,?,?,?,?)');if($s){$s->bind_param('iisssdsi',$pid,$cv,$date,$category,$desc,$amount,$rv,$managerId);if($s->execute()){$s->close();set_flash('success','Expenditure recorded','The expense has been added to the monitoring ledger.');safe_redirect('programme/budgets.php');}$s->close();}$errors[]='The expenditure could not be saved.';}}
 else $errors[]='Choose a valid action.';
 }}
$budgetTotal=0.0;$expenseTotal=0.0;$budgets=[];$expenses=[];$monthly=[];
if($tableReady){$s=$conn->prepare('SELECT COALESCE(SUM(b.allocated_amount),0) total FROM programme_budgets b JOIN programmes p ON p.id=b.programme_id WHERE p.programme_manager_id=?');if($s){$s->bind_param('i',$managerId);$s->execute();$budgetTotal=(float)($s->get_result()->fetch_assoc()['total']??0);$s->close();}$s=$conn->prepare('SELECT b.*,p.name programme_name,c.name cohort_name,COALESCE((SELECT SUM(x.amount) FROM programme_expenditures x WHERE x.programme_id=b.programme_id AND (x.cohort_id <=> b.cohort_id)),0) spent FROM programme_budgets b JOIN programmes p ON p.id=b.programme_id LEFT JOIN cohorts c ON c.id=b.cohort_id WHERE p.programme_manager_id=? ORDER BY b.updated_at DESC');if($s){$s->bind_param('i',$managerId);$s->execute();$budgets=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}}
if($expenseReady){$s=$conn->prepare('SELECT COALESCE(SUM(x.amount),0) total FROM programme_expenditures x JOIN programmes p ON p.id=x.programme_id WHERE p.programme_manager_id=?');if($s){$s->bind_param('i',$managerId);$s->execute();$expenseTotal=(float)($s->get_result()->fetch_assoc()['total']??0);$s->close();}$s=$conn->prepare('SELECT x.*,p.name programme_name,c.name cohort_name FROM programme_expenditures x JOIN programmes p ON p.id=x.programme_id LEFT JOIN cohorts c ON c.id=x.cohort_id WHERE p.programme_manager_id=? ORDER BY x.expense_date DESC,x.id DESC LIMIT 100');if($s){$s->bind_param('i',$managerId);$s->execute();$expenses=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}$s=$conn->prepare("SELECT DATE_FORMAT(x.expense_date,'%b %Y') label, SUM(x.amount) total, DATE_FORMAT(x.expense_date,'%Y-%m') sort_key FROM programme_expenditures x JOIN programmes p ON p.id=x.programme_id WHERE p.programme_manager_id=? AND x.expense_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY sort_key,label ORDER BY sort_key");if($s){$s->bind_param('i',$managerId);$s->execute();$monthly=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($pageTitle)?> | Investhood IT</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>?v=20261026"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>?v=20261026"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=$flashes?>

<section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Financial oversight</span><h1>Budget &amp; Expenditure Monitoring</h1><p>Record programme allocations and expenditures, compare spending against available funds, and review recent spending trends. Amounts shown are based on records entered in this portal.</p></div></section>
<?php foreach($errors as $error):?><div class="pm-suite-alert"><?=e($error)?></div><?php endforeach;?><?php if(!$tableReady||!$expenseReady):?><div class="pm-suite-notice">Database setup is required. Import <code>database/programme_management_suite.sql</code> into the active application database.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Total allocated</small><strong>R <?=number_format($budgetTotal,2)?></strong><span>Recorded programme budgets</span></article><article class="pm-suite-kpi"><small>Total expenditure</small><strong>R <?=number_format($expenseTotal,2)?></strong><span>Recorded spending</span></article><article class="pm-suite-kpi"><small>Remaining funds</small><strong>R <?=number_format($budgetTotal-$expenseTotal,2)?></strong><span>Allocation less recorded expenditure</span></article><article class="pm-suite-kpi"><small>Budget utilisation</small><strong><?=$budgetTotal>0?number_format(($expenseTotal/$budgetTotal)*100,1):'0.0'?>%</strong><span>Expenditure as a share of allocation</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Record a budget allocation</h2><p>Set a programme-wide or cohort-specific budget.</p></div><form class="pm-suite-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="budget"><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Budget period</label><input name="fiscal_period" maxlength="40" value="Current period" required></div><div class="pm-suite-field"><label>Allocated amount (ZAR)</label><input name="allocated_amount" type="number" min="0" step="0.01" required placeholder="0.00"></div><div class="pm-suite-field"><label>Notes</label><textarea name="notes" rows="2" maxlength="3000"></textarea></div><button class="pm-suite-btn" type="submit" <?=$tableReady?'':'disabled'?>>Save allocation</button></form>
<div class="pm-suite-panel-head"><h2>Record expenditure</h2><p>Capture an expense against a programme or cohort.</p></div><form class="pm-suite-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="expense"><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Date</label><input type="date" name="expense_date" required value="<?=date('Y-m-d')?>"></div><div class="pm-suite-field"><label>Amount (ZAR)</label><input type="number" name="amount" min="0.01" step="0.01" required></div></div><div class="pm-suite-field"><label>Category</label><input name="category" maxlength="100" required placeholder="Training, travel, equipment…"></div><div class="pm-suite-field"><label>Description</label><input name="description" maxlength="255" required></div><div class="pm-suite-field"><label>Reference number (optional)</label><input name="reference_number" maxlength="100"></div><button class="pm-suite-btn" type="submit" <?=$expenseReady?'':'disabled'?>>Record expenditure</button></form></section>
<div><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Budget allocations</h2><p>Budget-level spending estimates are calculated against matching programme/cohort records.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Programme / cohort</th><th>Period</th><th>Allocated</th><th>Recorded spend</th><th>Remaining</th></tr></thead><tbody><?php if(!$budgets):?><tr><td colspan="5" class="pm-suite-empty">No budget allocations recorded yet.</td></tr><?php else:foreach($budgets as $b):$remaining=(float)$b['allocated_amount']-(float)$b['spent'];?><tr><td><strong><?=e($b['programme_name'])?></strong><span class="pm-suite-muted"><?=e($b['cohort_name']??'Programme-wide')?></span></td><td><?=e($b['fiscal_period'])?></td><td>R <?=number_format((float)$b['allocated_amount'],2)?></td><td>R <?=number_format((float)$b['spent'],2)?></td><td><span class="pm-suite-pill <?=$remaining<0?'bad':'good'?>">R <?=number_format($remaining,2)?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Recent spending trend</h2><p>Monthly expenditure from the last six months with recorded activity.</p></div><?php if(!$monthly):?><div class="pm-suite-empty">No expenditure trend data available yet.</div><?php else:$maxMonth=max(array_map(fn($r)=>(float)$r['total'],$monthly));?><div class="pm-suite-chart"><?php foreach($monthly as $m):$height=$maxMonth>0?max(4,((float)$m['total']/$maxMonth)*100):4;?><div class="pm-suite-chart-item"><div class="pm-suite-chart-bar" style="height:<?=$height?>%" title="R <?=number_format((float)$m['total'],2)?>"></div><strong><?=number_format((float)$m['total']/1000,1)?>k</strong><?=e($m['label'])?></div><?php endforeach;?></div><?php endif;?></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Expenditure ledger</h2><p>Latest 100 expense records.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Date</th><th>Item</th><th>Programme / cohort</th><th>Amount</th></tr></thead><tbody><?php if(!$expenses):?><tr><td colspan="4" class="pm-suite-empty">No expenditure records yet.</td></tr><?php else:foreach($expenses as $x):?><tr><td><?=e(date('d M Y',strtotime($x['expense_date'])))?></td><td><strong><?=e($x['description'])?></strong><span class="pm-suite-muted"><?=e($x['category'])?><?=!empty($x['reference_number'])?' · Ref '.e($x['reference_number']):''?></span></td><td><?=e($x['programme_name'])?><span class="pm-suite-muted"><?=e($x['cohort_name']??'Programme-wide')?></span></td><td><strong>R <?=number_format((float)$x['amount'],2)?></strong></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></div>
